"""Evidence-linked hackathon assessment; rubric judgment is not a measured accuracy."""
import json,html,xml.etree.ElementTree as ET
from pathlib import Path
R=Path(__file__).resolve().parents[2];O=R/'reports/evaluation-2026-11-23'
load=lambda name:json.loads((O/name).read_text(encoding='utf-8'))
retrieval=load('retrieval-evaluation.json');browser=load('browser-checks.json');checks=load('checks.json')
xml=ET.parse(O/'test_retrieval_imports.xml').getroot();suites=list(xml.iter('testsuite'));count=sum(int(s.attrib.get('tests',0)) for s in suites)
for row in checks:
 if row['name']=='test_retrieval_imports':
  totals={key:sum(int(s.attrib.get(key,0)) for s in suites) for key in ['failures','errors','skipped']}
  row.update(tests=count,**totals,exit_code=int(bool(totals['failures']+totals['errors'])))
(O/'checks.json').write_text(json.dumps(checks,indent=2))
passed=sum(x.get('pass',0) if x['name']=='javascript' else x['tests']-x.get('skipped',0)-x.get('failures',0)-x.get('errors',0) for x in checks)
live=load('live-groq.json') if (O/'live-groq.json').exists() else None
esc=html.escape
def table(headers,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+esc(str(x))+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def link(name,title=None):return '<a href="'+esc(name)+'">'+esc(title or name)+'</a>'
body='''<header><p>CONTEXTIQ · 23 NOVEMBER 2026</p><h1>Hackathon readiness: 8.2 / 10</h1><p>An engineering assessment of the demo prototype. Not a judge’s score, model accuracy, security certification or production-readiness score.</p></header>
<h2>What changed</h2><ul><li>Tara now has SQLite-backed, owner-scoped knowledge chunks covering platform guidance, reviewed guides, current calculations, customers, invoices, bills, plans, recent ledger entries, purchase evidence and price watches.</li><li>Local word/character TF-IDF cosine retrieval chooses relevant sources. This is a sparse-vector index, not a newly trained neural latent space. Source records refresh before retrieval.</li><li>With separate record-sharing consent, the configured Groq model receives selected evidence and deterministic calculations, then returns an answer, concise rationale, assumptions and citation IDs.</li><li>Unknown citations, unsupported quoted currency amounts, unauthorized action claims, invalid output and verdicts that conflict with the code-calculated scenario trigger fallback. Those checks do not prove every model sentence is correct.</li><li>Cash scenarios now cover 1–90 days, month-end and fortnight questions, an exact client, receipt dates/delays, hypothetical cash and expenses. An editor previews daily results without changing the ledger.</li><li>CSV preview/confirm supports customers, bills, single-line draft invoices and transactions. It validates amounts/dates and skips duplicates. Transactions affect recorded cash only after confirmation; invoices are never automatically sent.</li><li>Owner-only JSON export provides a portable copy of key records. Parallel session/profile loading reduces one startup dependency. The existing bundled deployment and meaningful initial HTML remain.</li><li>Demo sessions remain without sign-in, as requested. SQLite remains the database. No paid disk or new external database was provisioned.</li></ul>
<h2>How to try it</h2><ol><li>Open <a href="https://context-iq-v2-0.vercel.app/">ContextIQ</a> and start a fresh demo after the backend redeploy.</li><li>In AI &amp; Privacy, enable question understanding and the separate relevant-record-sharing choice if you want Groq to read retrieved records. This sends selected financial context to the configured provider.</li><li>Ask a financial question, then expand Sources Tara retrieved and View details. The privacy toggle can disable external record reasoning while record-based assistance stays available.</li><li>Open Back office → Cash forecast → Build a read-only cash scenario. Change hypothetical cash or a client delay and inspect the decision and daily numbers.</li><li>Use Back office → Import &amp; export with anonymized CSV copies. Preview, inspect errors/duplicates, then confirm. Download an owner-scoped JSON copy if needed.</li></ol>'''
body+='<h2>Measured evidence</h2>'+table(['Check','Result','Practical limit'],[
['Automated suites',str(passed)+' local checks passed','Python suites run in isolated processes. PostgreSQL tests are skipped locally because no PostgreSQL service is configured.'],
['Fresh retrieval bank',f"Primary source hit@1 {retrieval['primary_source_hit_at']['1']:.1%}; hit@8 {retrieval['primary_source_hit_at']['8']:.1%}; MRR@8 {retrieval['mrr_at_8']:.3f}; N=16",'Newly frozen developer-authored bank, not external human labeling. Primary-source hit rate is not full retrieval recall/precision or answer accuracy.'],
['Arithmetic oracle',f"{retrieval['oracle_passed']}/{retrieval['oracle_n']} controlled daily cash scenarios matched",'Independent calculation loops over synthetic controlled records; not a bank reconciliation study.'],
['Browser flows',str(sum(browser['checks'].values()))+'/'+str(len(browser['checks']))+' passed','Real local browser → API → isolated SQLite: consent, visible retrieval, scenario no-mutation, confirmed imports and export.'],
['Desktop and phone layouts',str(len(browser['pages']))+' route/viewport combinations; '+str(sum(len(p['violations']) for p in browser['pages']))+' detected axe rule violations; '+str(sum(p['overflow'] for p in browser['pages']))+' page overflows','Automated accessibility is incomplete. Physical-device, screen-reader and actual trader usability tests remain.'],
['SQLite backup/restore',str(retrieval['sqlite_restore_integrity'])+'; '+str(retrieval['tables_checked'])+' table counts checked','Fresh local restore and integrity check. Does not make the hosted filesystem persistent.'],
['Live Groq smoke',str(live['real_model_answer_count'])+'/'+str(len(live['rows']))+' genuine retrieval-backed model answers observed' if live else 'Awaiting backend rollout / live check','Two prompts do not establish general Groq accuracy, F1, hallucination rate or production capacity.']])
body+='''<h2>Hackathon rubric assessment</h2>'''+table(['Criterion','My score','Reason'],[
['Real-world usefulness','22 / 25','Connected invoicing, receipt tracking, bill coverage and client-delay scenarios solve a clear business problem. No trader outcome evidence yet.'],
['Technology actually works','22 / 25','Working database, deterministic finance, scoped retrieval/Groq integration, exact source links, imports and regression evidence. Retrieval misses and arbitrary-language reasoning still need evaluation.'],
['Simplicity','16 / 20','Coherent interface, direct answers, visual Tara and evidence on demand. Several financial terms and advanced controls remain; real-user first-use testing is pending.'],
['Speed, safety and readiness','10 / 15','Consent, scoped data, CSRF, approvals and duplicate protection are tested. Free-host cold starts, ephemeral SQLite, demo identity and simulated payments remain meaningful limits.'],
['Product subtotal','70 / 85 ≈ 82.4%','Rounded to 8.2/10 as a subjective prototype-readiness assessment. It is not a measured model metric.'],
['PPT presentation','Not assessed / 15','The mandatory final deck has not been reviewed in this update. Do not treat it as full marks.'],
['Live video bonus','Not awarded automatically','A working three-minute story video exists from the previous release. Judges determine whether its content and submission qualify; the new retrieval/import controls are not shown in that older recording.']])
body+='''<h2>Remaining gaps, plainly</h2><ul><li><b>No independent user validation yet.</b> Developer tests cannot establish that a busy trader understands the product immediately.</li><li><b>Free SQLite hosting can reset.</b> The export and tested backup tooling help portability; always-on durable storage is not solved by adding a retrieval index.</li><li><b>Model grounding is bounded.</b> Citation existence and currency checks do not establish citation entailment, correct client attribution or universal reasoning accuracy. The retriever uses bounded recent records (for example the latest 200 ledger entries), not an unlimited semantic memory.</li><li><b>External records are optional.</b> Groq record reasoning needs both privacy choices enabled. The application intentionally does not silently broaden existing question-only consent.</li><li><b>Payments remain simulated.</b> The agent never approves or sends money. Demo identity is not production account security.</li><li><b>Language coverage is bounded.</b> Named-client/date parsing can ask for clarification. Multi-client conditions and arbitrary long-range questions are not guaranteed.</li></ul>
<h2>Ten-minute trader usability protocol</h2><p>Use fictional or anonymized records and ask permission to observe. Run this with 3–5 shopkeepers or freelancers before claiming user validation.</p>'''+table(['Task','Observe / record'],[
['Create a ₹1,250 draft invoice for a demo client','Can the participant find Customers/Invoices without hints? Record completion time, wrong turns and whether the total is understood.'],
['Record a ₹500 partial receipt','Do they understand this records money already received rather than collecting it? Verify ₹750 outstanding and one ₹500 ledger income.'],
['Ask whether rent and EMI fit if that client pays late','Can they identify the verdict, period, selected client and assumptions? Do they inspect evidence before deciding?'],
['Preview a smaller cash buffer without changing real records','Can they distinguish a hypothetical scenario from a posted transaction? Verify the ledger stays unchanged.'],
['Minimize/reopen Tara; locate record-sharing controls','Can they recover the conversation and explain which information leaves the backend?']])+'''<p>For each task record success without help, time, errors and the participant’s own words. Ask “What did you think would happen?” and “What part would you not trust?” Do not coach them first. Report participant count and anonymized feedback; do not convert a handful of observations into statistical accuracy or a fabricated testimonial.</p>'''
body+='<h2>Inspect the evidence</h2><p>'+' · '.join(link(n) for n in ['retrieval-evaluation.json','browser-checks.json','checks.json','test_retrieval_imports.xml']+(['live-groq.json'] if live else []))+'</p><p>Core source: '+esc('app/v2_retrieval.py · app/v2_scenario_engine.py · app/v2_imports.py')+'</p>'
css='''body{font:16px/1.65 system-ui;background:#f2f4ef;color:#172218;max-width:1150px;margin:auto;padding:30px}header{background:#172218;color:white;padding:35px;border-radius:20px}header p:first-child{color:#b6ed4b;font-weight:700}h1{font-size:36px}h2{margin-top:35px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:12px;border:1px solid #ced7c5;text-align:left;vertical-align:top}th{background:#e1edcf}a{color:#345b20}li{margin:9px 0}@media(max-width:600px){body{padding:15px}h1{font-size:28px}}'''
(O/'ContextIQ readiness report.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ContextIQ readiness review</title><style>'+css+'</style>'+body+'</html>',encoding='utf-8')
print('Readiness report created; local checks',passed)
